import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { createHash } from 'node:crypto';
const source = fs.realpathSync(process.cwd());
const { greenPassScope, GREEN_CONTRACTS } = await import(pathToFileURL(path.join(source, 'supervisor/green-pass.mjs')));
const digest = value => createHash('sha256').update(value).digest('hex');
const git = (args, cwd = source) => {
  const result = spawnSync('git', ['-C', cwd, ...args], { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
  if (result.status !== 0) throw Error(result.stderr || result.error?.message || `git ${args[0]} failed`);
  return result.stdout.trim();
};
const main = git(['rev-parse', 'main']), bootstrap = git(['rev-parse', 'HEAD']);
git(['merge-base', '--is-ancestor', main, bootstrap]);
const workspace = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'eng396-r566-real-')));
const bindings = { ...GREEN_CONTRACTS.bindings, activatedAt: new Date().toISOString() };
const brain = bindings.brain;
const result = { schema: 'green-real-candidates/v1', node: process.version, main, bootstrap,
  source, workspace, bindings: GREEN_CONTRACTS.bindings, activation: 'hypothetical eligibility binding only; no deployment config written',
  source_sha256: Object.fromEntries(['supervisor/green-pass.mjs', 'supervisor/green-manifest.mjs', 'supervisor/green-contracts.json'].map(file => [file, digest(fs.readFileSync(path.join(source, file)))])),
  checks: [], retained_branches: [] };
let success = false;
const record = (label, expected, overrides = {}) => {
  const options = { ...brain, workspace, base: bootstrap, head: overrides.head ?? git(['rev-parse', 'HEAD'], workspace), bindings, run: 'R-566', ...overrides };
  const receipt = greenPassScope(options);
  result.checks.push({ label, head: options.head, eligible: receipt.eligible, code: receipt.code ?? null, reason: receipt.reason ?? null,
    ...(receipt.eligible ? { components: receipt.manifest.components, manifest_sha256: receipt.manifest.sha256 } : {}) });
  assert.equal(receipt.eligible, expected === null, JSON.stringify(receipt));
  if (expected) assert.equal(receipt.code, expected, JSON.stringify(receipt));
  return receipt;
};
const branch = label => {
  const name = `proof/R-566-final-${label}`;
  git(['switch', '--no-track', '-c', name, bootstrap], workspace); result.retained_branches.push(name);
};
const commitFile = (file, bytes, label) => {
  fs.writeFileSync(path.join(workspace, file), bytes); git(['add', file], workspace); git(['commit', '-qm', `R-566 real-main ${label} control`], workspace);
};
try {
  git(['worktree', 'add', '--no-track', '-b', 'proof/R-566-final-renderer', workspace, bootstrap]); result.retained_branches.push('proof/R-566-final-renderer');
  const original = fs.readFileSync(path.join(workspace, 'board/render.mjs'), 'utf8');
  assert.equal(git(['show', `${main}:board/render.mjs`]), original.trim(), 'candidate source is the exact real-main renderer');
  const candidate = original.replace('width = 120,', 'width = 121,'); assert.notEqual(candidate, original);
  commitFile('board/render.mjs', candidate, 'renderer');
  result.renderer = { before_sha256: digest(original), after_sha256: digest(candidate), diff: git(['diff', bootstrap, 'HEAD', '--', 'board/render.mjs'], workspace) };
  record('renderer', null);
  // Actual focused execution uses only the intended renderer and its pinned rows
  // dependency, after source admission has completed without importing it.
  const { render } = await import(pathToFileURL(path.join(workspace, 'board/render.mjs')));
  const snapshot = { memory: 0, herdr: 'x'.repeat(150), slot: { state: 'idle', heldSeconds: 0, queueLength: 0 }, rows: [] };
  assert.equal(render(snapshot).split('\n')[0].length, 121);
  assert.equal(render(snapshot, { width: 80 }).split('\n')[0].length, 80);
  result.renderer.validation = { exact_committed_bytes: true, default_width: 121, explicit_width: 80 };
  // Check the final environment fingerprint, added after the single combined
  // suite. It must detect both an existing selector change and a new Git key.
  const rendererOptions = { head: git(['rev-parse', 'HEAD'], workspace) };
  for (const key of ['GIT_CONFIG_SYSTEM', 'GIT_R566_NEW_SELECTOR']) {
    const previous = process.env[key];
    try { process.env[key] = '/private/tmp/not-an-approved-git-input'; record(`environment-${key}`, 'GREEN_REACH_UNKNOWN', rendererOptions); }
    finally { if (previous === undefined) delete process.env[key]; else process.env[key] = previous; }
  }
  record('environment-restored-renderer', null);
  for (const [label, file, code] of [
    ['bch-entry', 'supervisor/reconcile.mjs', 'GREEN_BCH_CONSUMED'],
    ['promotion-authority', 'test/helpers/run.mjs', 'GREEN_SELF_AUTHORITY'],
    ['manifest', 'supervisor/green-contracts.json', 'GREEN_SELF_AUTHORITY'],
    ['boundary', 'board/rows.mjs', 'GREEN_BOUNDARY_CHANGED'],
  ]) {
    branch(label); const bytes = fs.readFileSync(path.join(workspace, file), 'utf8');
    commitFile(file, bytes + '\n// R-566 refusal control\n', label); record(label, code);
  }
  record('foreign-project-target', 'GREEN_IDENTITY_MISMATCH', { repo: '/Users/rewt/development/bastian/bch-cloak', org: '/Users/rewt/development/bastian/.org' });
  record('expired-activation', 'GREEN_EXPIRED', { bindings: { ...bindings, activatedAt: new Date(Date.now() - 10 * 86400000).toISOString() } });
  assert.equal(git(['status', '--porcelain'], workspace), ''); success = true;
} finally {
  result.success = success;
  if (success) { git(['worktree', 'remove', workspace]); result.workspace_removed = true; }
  fs.writeFileSync('/tmp/eng396-r566-real-candidates.json', JSON.stringify(result, null, 2) + '\n');
}
console.log(JSON.stringify({ success, main, bootstrap, checks: result.checks.map(({label,eligible,code}) => ({label,eligible,code})), retained_branches: result.retained_branches }));
